    const rules=policy?.inventoryFeatures?.progressRules;if(rules===undefined)return;
    if(!Array.isArray(rules)||rules.length>100)throw Error('연결 진행 규칙을 다시 확인하세요.');
    const seenRules=new Set();for(const rule of rules){if(!rule||typeof rule!=='object'||Array.isArray(rule)||Object.keys(rule).some(k=>!['from','to','enabled','progress'].includes(k))||typeof rule.enabled!=='boolean'||!['진행','완료'].includes(rule.progress))throw Error('연결 진행 규칙을 다시 확인하세요.');if(!rule.enabled)continue;const key=rule.from+'|'+rule.to;if(!Object.hasOwn(types,rule.from)||!Object.hasOwn(types,rule.to)||rule.from===rule.to||seenRules.has(key))throw Error('알 수 없거나 중복된 연결 진행 규칙입니다.');seenRules.add(key);}
    const targets=new Map();for(const child of linked)for(const line of child.lines)for(const ref of allocations(child,line)){
      const source=db.documents.find(d=>d.id===ref.documentId),matches=source&&rules.filter(r=>r.enabled&&r.from===source.type&&r.to===child.type);if(!matches?.length)continue;
      if(!active(source)||!nextTypes[source.type]?.includes(child.type))throw Error('연결 진행 규칙의 원본 전표가 변경됐습니다.');
      const rule=matches[0],key=source.id+'|'+rule.progress;if(!targets.has(key))targets.set(key,{source,progress:rule.progress,selections:new Map()});
      if(source.type==='plan'){const lines=source.lines.filter(l=>l.item===ref.item&&(!ref.sourceLineId||l.lineId===ref.sourceLineId));if(lines.length!==1||lines[0].lineId&&!ref.sourceLineId)throw Error('연결 진행 규칙의 원본 품목행을 확인하세요.');const original=lines[0],id=original.lineId||original.item;targets.get(key).selections.set(id,{documentId:source.id,item:original.item,...(original.lineId?{lineId:original.lineId}:{})});}
    }
    const sourceStates=new Map();for(const target of targets.values()){const old=sourceStates.get(target.source.id);if(old&&old!==target.progress)throw Error('동일 원본에 서로 다른 진행 변경 규칙이 적용됐습니다.');sourceStates.set(target.source.id,target.progress);if(target.source.type==='plan')planLineProgress(db,{selections:[...target.selections.values()],progress:target.progress});else transition(db,{ids:[target.source.id],...(purchasingTypes.includes(target.source.type)?{progress:target.progress}:{status:target.progress})});}
    validateLinks(db);validateStock(db);
  }

function command(input,op,payload={},policy){
    if(!commandNames.includes(op)||!payload||typeof payload!=='object'||Array.isArray(payload))throw Error('지원하지 않는 작업 또는 요청 자료입니다.');
    const db=applyPolicy(input,policy);payload=clone(payload);let result;
    if(op==='master')result=saveMaster(db,payload);
    else if(op==='itemBatch'){
      if(!Array.isArray(payload.records)||!payload.records.length||payload.records.length>10000)throw Error('일괄 품목은 1~10,000행을 입력하세요.');
      if(new Set(payload.records.map(x=>String(x.record?.code||'').trim())).size!==payload.records.length)throw Error('일괄 품목코드가 중복됩니다.');
      result=payload.records.map(row=>saveMaster(db,{key:'items',record:row.record,originalCode:row.originalCode}));
    }
    else if(op==='itemConfig'){if(!I)throw Error('품목 모듈을 다시 불러오세요.');db.settings.itemRegistration=I.validateConfig(payload.config);result=db.settings.itemRegistration;log(db,'품목 입력화면·기능설정 변경');}
    else if(op==='document')result=saveDoc(db,payload);
    else if(op==='purchasePlanGenerate'){if(!Array.isArray(payload.documents)||!payload.documents.length||payload.documents.length>200||payload.documents.some(d=>d.id||d.type!=='purchaseorder'||d.generatedFrom!=='purchase-plan'))throw Error('발주계획 발주서 일괄 생성 자료를 확인하세요.');result=payload.documents.map(d=>saveDoc(db,d));}
    else if(op==='purchaseRoom'){const PR=purchaseRoomModule();if(!PR)throw Error('구매실 업무 모듈을 다시 불러오세요.');const out=PR.command(db,payload,api);db.settings.purchaseRoom=PR.validateStore(out.store,db,api);result=out.result;log(db,'구매실 업무 처리: '+payload.action);}
    else if(op==='convert')result=convert(db,payload);
    else if(op==='transition')result=transition(db,payload);
    else if(op==='planLineProgress')result=planLineProgress(db,payload);
    else if(op==='payment')result=payment(db,payload);
    else if(op==='removePayment'){db.payments=db.payments.filter(x=>x.id!==payload.id);log(db,'수금/지급 취소');}
    else if(op==='bom')result=setBom(db,payload);
    else if(op==='rename')result=rename(db,payload);
    else if(op==='bor'){requireCode(db,'items',payload.product);requireCode(db,'processes',payload.process);requireCode(db,'resources',payload.resource);const row={...payload,minutes:num(payload.minutes,'소요시간',.000001)};db.bor=db.bor.filter(x=>!(x.product===row.product&&x.process===row.process));db.bor.push(row);log(db,'BOR 저장');result=row;}
    else if(op==='price'){requireCode(db,'items',payload.item);if(payload.group)requireCode(db,'pricegroups',payload.group);else requireCode(db,'partners',payload.partner);const row={...payload,group:payload.group||'',partner:payload.group?'':payload.partner,price:num(payload.price,'특별단가')};db.prices=db.prices.filter(x=>!(x.item===row.item&&x.partner===row.partner&&(x.group||'')===row.group&&Boolean(x.buy)===Boolean(row.buy)));db.prices.push(row);result=row;}
    else if(op==='mapping'){requireCode(db,'shops',payload.shop);requireCode(db,'items',payload.item);if(!payload.external)throw Error('쇼핑몰 품목코드를 입력하세요.');db.mappings=db.mappings.filter(x=>!(x.shop===payload.shop&&x.external===payload.external));db.mappings.push(payload);result=payload;}
    else if(op==='settings'){if(Object.hasOwn(payload,'purchaseRoom'))throw Error('구매실 설정은 전용 업무 명령으로 변경하세요.');db.settings={...db.settings,...payload};validateStock(db);}
    else if(op==='formSave'){db.settings.customization=F.save(db.settings.customization,payload.key,payload.context,payload.form);result=payload.form;}
    else if(op==='formActivate'){db.settings.customization=F.activate(db.settings.customization,payload.key,payload.context,payload.id);}
    else if(op==='formDelete'){db.settings.customization=F.remove(db.settings.customization,payload.key,payload.id);}
    else if(op==='formRules'){db.settings.customization=F.rules(db.settings.customization,payload.key,payload.rules);}
    else if(op==='bulkprice'){for(const d of db.documents.filter(d=>payload.ids.includes(d.id))){if(d.accounted)throw Error('회계반영을 취소하세요.');saveDoc(db,{...d,lines:d.lines.map(l=>({...l,price:money(l.price*(1+num(payload.percent,'변경률',-100)/100))}))});}}
    else if(op==='rebuild'){validateLinks(db);validateStock(db);log(db,'연결 잔량·재고 재검증 완료');}
    else throw Error('지원하지 않는 작업입니다.');
    if(['document','convert','purchasePlanGenerate'].includes(op))applyLinkedProgressRules(db,result,policy);
    guardClosedPeriods(input,db);
    if(db.settings.purchaseRoom)db.settings.purchaseRoom=purchaseRoomModule().validateStore(db.settings.purchaseRoom,db,api);
    for(const p of db.masters.partners)for(const side of ['receivable','payable'])if(outstanding(db,side,p.code)<-.001)throw Error('수금/지급 잔액을 초과하게 됩니다. 수금/지급 기록을 먼저 취소하세요.');
    return {db,result};
  }

function candidateRows(db,options={}){
   if(options.from)date(options.from,'기간 시작');if(options.to)date(options.to,'기간 종료');if(options.from&&options.to&&options.from>options.to)throw Error('조회 기간을 확인하세요.');
   const query=String(options.query||'').trim().toLocaleLowerCase('ko-KR');
   return db.documents.filter(d=>d.type==='plan'&&C.active(d)&&(!options.ids||options.ids.includes(d.id))&&(!options.from||d.date>=options.from)&&(!options.to||d.date<=options.to)).flatMap(d=>C.remaining(db,d,'purchaseorder').filter(l=>l.qty>0&&C.purchasingLineState(d,l).progress!=='완료').map(line=>{
     const item=C.master(db,'items',line.item),supplier=line.supplier||item?.supplier||'',partner=C.master(db,'partners',supplier),original=d.lines.find(l=>line.lineId?l.lineId===line.lineId:l.item===line.item);
     return {key:d.id+'|'+(line.lineId||line.item),...(line.lineId?{lineId:line.lineId}:{}),documentId:d.id,date:d.date,item:line.item,name:item?.name||line.item,spec:item?.spec||'',unit:item?.unit||'',dueDate:original.dueDate||d.dueDate||'',warehouse:d.warehouse,supplier,supplierName:partner?.name||'',supplierValid:!!partner&&!partner.disabled,disabled:!item||item.disabled||!C.master(db,'warehouses',d.warehouse)||C.master(db,'warehouses',d.warehouse).disabled,originalQty:original.qty,processedQty:qty(original.qty-line.qty),qty:line.qty,price:line.price||0,discount:line.discount||0,memo:line.memo||''};
   })).filter(row=>!query||[row.documentId,row.item,row.name,row.spec,row.supplierName].some(v=>String(v).toLocaleLowerCase('ko-KR').includes(query))).sort((a,b)=>a.date.localeCompare(b.date)||a.documentId.localeCompare(b.documentId)||a.item.localeCompare(b.item,'ko-KR',{numeric:true}));
 }

function preview(db,input={}){
   const request=clone(input),grouping=request.grouping||'supplier-date-line';if(!modes.some(([key])=>key===grouping))throw Error('정리 방식을 선택하세요.');
   const generationDate=date(request.date||C.today(),'생성일');if(request.dueDate)date(request.dueDate,'납기일');
   if(!Array.isArray(request.selections)||!request.selections.length||request.selections.length>500)throw Error('발주계획 품목을 1~500행 선택하세요.');
   const policy=grouping==='custom'?{splitSupplier:request.custom?.splitSupplier!==false,splitDueDate:request.custom?.splitDueDate!==false,mergeItems:request.custom?.mergeItems===true}:{splitSupplier:grouping.startsWith('supplier-'),splitDueDate:grouping.startsWith('supplier-'),mergeItems:grouping.endsWith('-item')};
   const issue=(key,message)=>({key,message}),issues=[],selected=[],seen=new Set(),current=new Map(candidateRows(db).map(row=>[row.key,row])),facts=[],sourceFacts=new Map(),itemFacts=new Map();
   for(const selection of request.selections){
     const key=selection.documentId+'|'+(selection.lineId||selection.item);if(seen.has(key)){issues.push(issue(key,'같은 발주계획 품목을 중복 선택했습니다.'));continue;}seen.add(key);
     const row=current.get(key),source=db.documents.find(d=>d.id===selection.documentId);if(!row||!source||row.item!==selection.item){issues.push(issue(key,'원본이 취소·완료되었거나 처리할 잔량이 없습니다.'));continue;}
     const original=source.lines.find(l=>selection.lineId?l.lineId===selection.lineId&&l.item===selection.item:l.item===selection.item),item=C.master(db,'items',selection.item);facts.push(row);sourceFacts.set(source.id,source);itemFacts.set(item?.code,item);
     try{
       if(row.disabled)throw Error('사용 중인 품목과 창고를 선택하세요.');const amount=positive(selection.qty===undefined?row.qty:selection.qty);if(amount>row.qty+.000001)throw Error('원본 발주계획의 잔량을 초과했습니다.');
       const supplier=policy.splitSupplier?(selection.supplier===undefined?row.supplier:selection.supplier):request.partner,partner=C.master(db,'partners',supplier);if(!supplier||!partner||partner.disabled)throw Error(policy.splitSupplier?'품목 구매처를 지정하세요.':'1장으로 생성할 발주서의 거래처를 지정하세요.');
       const dueDate=selection.dueDate||row.dueDate||request.dueDate;date(dueDate,'납기일');
       const line=clone(original);delete line.supply;delete line.tax;delete line.total;delete line.sourceLineId;delete line.lineId;delete line.planAllocations;delete line.progress;
       line.qty=amount;line.dueDate=dueDate;line.planAllocations=[{documentId:source.id,item:line.item,qty:amount,...(original.lineId?{sourceLineId:original.lineId}:{})}];line.importedFrom=[...(line.importedFrom||[]),{documentId:source.id,type:'plan',date:source.date,item:line.item,qty:amount,mode:'linked'}];
       selected.push({key,source,line,supplier,header:header(source),dueDate});
     }catch(e){issues.push(issue(key,e.message));}
   }
   const groups=new Map();for(const row of selected){
     const context=stable(row.header),key=stable([policy.splitSupplier?row.supplier:request.partner,policy.splitDueDate?row.dueDate:'',context]);
     if(!groups.has(key))groups.set(key,{key,partner:row.supplier,context,header:row.header,rows:[]});groups.get(key).rows.push(row);
   }
   if(!policy.splitSupplier&&!policy.splitDueDate&&groups.size>1)issues.push(issue('header','1장 생성은 창고·통화·부가세율·담당자·프로젝트·추가 머리 항목이 같아야 합니다. 다른 조건은 나누어 선택하세요.'));
   const documents=[];
   for(const group of groups.values()){
     const lines=[];for(const row of group.rows){const line=row.line,existing=policy.mergeItems?lines.find(l=>l.item===line.item):null;
       if(existing){
         const comparable=value=>Object.fromEntries(Object.entries({...value,price:Number(value.price||0),discount:Number(value.discount||0),memo:value.memo||'',custom:value.custom||{}}).filter(([key])=>!['qty','dueDate','planAllocations','importedFrom','lineId'].includes(key)));
         if(stable(comparable(existing))!==stable(comparable(line))){issues.push(issue(row.key,'품목별 합산할 단가·할인·적요·추가 항목이 다릅니다. 라인별 정리 방식을 선택하세요.'));continue;}
         existing.qty=qty(existing.qty+line.qty);existing.planAllocations.push(...line.planAllocations);existing.importedFrom.push(...line.importedFrom);if(existing.dueDate!==line.dueDate)existing.dueDate='';
       }else lines.push({...line,lineId:'PL'+(lines.length+1)});
     }
     const dueDates=[...new Set(group.rows.map(r=>r.dueDate))],doc={...clone(group.header),type:'purchaseorder',date:generationDate,partner:group.partner,dueDate:dueDates.length===1?dueDates[0]:'',status:'진행',accounted:false,generatedFrom:'purchase-plan',planGeneration:{grouping,policy:clone(policy),sourceIds:[...new Set(group.rows.map(r=>r.source.id))]},memo:request.memo||'',lines};
     documents.push(doc);
   }
   if(documents.length>200)issues.push(issue('limit','한 번에 생성할 발주서는 200장까지 가능합니다. 선택 범위를 줄이세요.'));
   const summary={plans:new Set(selected.map(r=>r.source.id)).size,selectedLines:selected.length,documents:documents.length,lines:documents.reduce((sum,d)=>sum+d.lines.length,0),quantity:qty(selected.reduce((sum,r)=>sum+r.line.qty,0)),total:C.money(documents.reduce((sum,d)=>sum+C.totals(d).total,0)),suppliers:[...new Set(documents.map(d=>d.partner))]};
   return {documents,issues,summary,request:{...request,date:generationDate,grouping},snapshot:stable({facts,sources:[...sourceFacts.values()],items:[...itemFacts.values()],documents,issues})};
 }

function commit(db,prepared,policy){
   if(!prepared||typeof prepared.snapshot!=='string'||!prepared.request)throw Error('생성 미리보기를 먼저 확인하세요.');
   const current=preview(db,prepared.request);if(current.issues.length)throw Error(current.issues[0].message);if(current.snapshot!==prepared.snapshot||stable(current.documents)!==stable(prepared.documents))throw Error('발주계획·품목·잔량 또는 미리보기가 변경됐습니다. 미리보기를 다시 확인하세요.');
   return C.command(db,'purchasePlanGenerate',{documents:current.documents},policy);
 }
